import { LogRecordAdditionalColumns } from './log-record-additional-columns';
import { LogRecordEventType } from './log-record-event-type';
import { LogRecordStatus } from './log-record-status';
/**
 * A single log record.
 */
export interface LogRecord {
    additionalColumns?: LogRecordAdditionalColumns;
    /**
     * The content of the log record.
     */
    content?: string;
    eventType?: LogRecordEventType;
    status?: LogRecordStatus;
    /**
     * The timestamp of the log record, in UTC milliseconds.
     */
    timestamp?: number;
}
